ruleToc.chapterList:
@css:
.title> b,.book_list>ul>li


@js:
list=[]
$=result
for(i in $){
if(String($[i]).match(/<b/)){
	t=String($[i].text()).replace(new RegExp(book.name,''),'').replace(/（.*|\(.*/g,'');
		list.push({
				text: " 📖 【"+t+" 】 📖 ",
				vo: true
			})
	}
else{
		$[i].select("a").forEach(a=>{
				list.push({
						text: a.text(),
						href: a.attr("href")
					})
			})
	}
}
list

